"""Publication retention contracts; optional native runs use generated bytes only.

Set KATANA_NEXTFLOW_COMMAND_JSON to the pinned Nextflow argv to execute the
native publication check. It invokes no aligner or biological computation and
does not delete task work or user files.
"""
from __future__ import annotations

import json
import hashlib
import os
from pathlib import Path
import shutil
import subprocess
import tempfile
import unittest


PIPELINE = Path(__file__).resolve().parents[1]
CONFIG = PIPELINE / "conf/upstream_modules.config"


class StoragePublicationContractTests(unittest.TestCase):
    def test_publication_revision_retains_the_frozen_and_preceding_source_identity(self):
        source = json.loads((PIPELINE / "UPSTREAM_SOURCE.json").read_text(encoding="utf-8"))
        changes = json.loads((PIPELINE / "INTEGRATION_CHANGES.json").read_text(encoding="utf-8"))
        original = next(row for row in source["files"] if row["destination"] == "conf/upstream_modules.config")
        entry = next(row for row in changes["changes"] if row["path"] == "conf/upstream_modules.config")
        self.assertEqual(original["sha256"], "0a32f38bce21b712643f68335fbd12cad61a9a083c84c00e00dcbedd18055284")
        self.assertEqual(entry["snapshot_sha256"], original["sha256"])
        revision = next(row for row in entry["integration_revisions"] if row["revision"] == "lean-upstream-publication-20261026")
        self.assertEqual(revision["previous_integrated_sha256"], "030e98a102ec950c8989f3b7b9d28846c85769b0b284b7034c1d0f3a6a64e47f")
        self.assertEqual(entry["integrated_sha256"], hashlib.sha256(CONFIG.read_bytes()).hexdigest())
        self.assertEqual(revision["integrated_sha256"], entry["integrated_sha256"])
        for name in ("scientific_modules_modified", "scientific_parameters_changed", "statistical_algorithms_changed", "bundle_artifact_inventory_changed"):
            self.assertIs(revision[name], False)

    def test_bundle_remains_canonical_and_only_rebuildable_index_is_omitted(self):
        config = CONFIG.read_text(encoding="utf-8")
        bundle = config.split("withName: 'KATANA_EXPORT'", 1)[1]
        self.assertIn("pattern: 'katana_bundle'", bundle)
        self.assertNotIn("enabled:", bundle)
        index = config.split("withName: 'STAR_GENOMEGENERATE'", 1)[1].split("withName:", 1)[0]
        self.assertIn('"${params.outdir}/reference_index"', index)
        self.assertIn("enabled: \"${ -> params.storage_mode != 'lean' }\"", index)

    def test_complete_bundle_still_receives_bam_references_and_native_tables(self):
        # Publishing fewer copies must not change declared producer->exporter
        # channels or turn the full bundle into a report-only reduced dataset.
        core = (PIPELINE / "workflows/katana_core.nf").read_text(encoding="utf-8")
        for expression in (
            "artifact('genome_fasta', it, 'refs/genome.fasta')",
            "artifact('gtf', it, 'refs/annotation.gtf')",
            "artifact('transcript_fasta', it, 'refs/transcripts.fasta')",
            "artifact('auxiliary', it, 'refs/genome.fasta.fai')",
            "artifact('bam', bam,",
            "artifact('bai', bai,",
            "artifact('quant', directory.resolve('quant.sf'),",
        ):
            with self.subTest(expression=expression):
                self.assertIn(expression, core)
        exporter = (PIPELINE / "modules/local/katana_export.nf").read_text(encoding="utf-8")
        self.assertIn("--profile full", exporter)

    def test_inline_expression_import_publisher_has_explicit_retention_override(self):
        config = CONFIG.read_text(encoding="utf-8")
        self.assertIn("'KATANA_(TXIMPORT|DESEQ2_CONTRAST|NORMALIZE|DESEQ2_METADATA)'", config)
        self.assertIn("def leanStorage = { params.storage_mode == 'lean' }", config)
        self.assertIn("enabled: \"${ -> params.storage_mode != 'lean' }\"", config)
        self.assertEqual(config.count("mode: \"${ -> params.storage_mode == 'lean' ? 'copy' : params.publish_dir_mode }\""), 3)
        self.assertNotIn("mode: {", config)
        self.assertNotIn("enabled: {", config)
        self.assertIn("native_models/dexseq_exon", config)
        self.assertIn("native_models/dtu/dexseq", config)
        self.assertIn("native_models/dtu/stager", config)
        self.assertIn("native_models/DEG", config)
        self.assertIn("native_models/salmon", config)
        # No destructive operation or move-publishing may be introduced by this
        # storage layer: live channels still consume their original task files.
        self.assertNotIn("mode: 'move'", config)
        self.assertNotIn("deleteDir", config)
        self.assertNotIn("rm -", config)


def _native_command():
    encoded = os.environ.get("KATANA_NEXTFLOW_COMMAND_JSON")
    if encoded:
        command = json.loads(encoded)
        if not isinstance(command, list) or not command or not all(isinstance(item, str) for item in command):
            raise ValueError("KATANA_NEXTFLOW_COMMAND_JSON must contain a nonempty string argv")
        return command
    executable = shutil.which("nextflow")
    return [executable] if executable else None


def _fixture(root: Path, mode: str, *, full_config=False):
    root.mkdir()
    # These extensions exercise publication only. They intentionally do not
    # masquerade as valid biological reads, alignments, references or results.
    outputs = {
        "TRIMGALORE": ["S1_val_1.fq.gz", "S1_val_2.fq.gz", "S1_trimming_report.txt", "versions.yml"],
        "FASTQC": ["S1_fastqc.html", "S1_fastqc.zip", "versions.yml"],
        "STAR_ALIGN": ["S1.Aligned.out.bam", "S1.unmapped_1.fastq.gz", "S1.Log.final.out", "S1.SJ.out.tab", "versions.yml"],
        "COLLATE_GENOME_BAM": ["S1.name_grouped.bam", "versions.yml"],
        "SAMTOOLS_SORT": ["S1.coordinate.bam", "versions.yml"],
        "SAMTOOLS_INDEX": ["S1.coordinate.bam.bai", "versions.yml"],
        "PREPARE_REFERENCES": ["genome.fasta", "annotation.gtf", "transcripts.fasta", "reference.sha256", "versions.yml"],
        "STAR_GENOMEGENERATE": ["star-index/Genome", "star-index/SA", "versions.yml"],
        "SALMON_GENOME_PROJECTION": ["S1/quant.sf", "S1/aux_info/meta_info.json", "S1/lib_format_counts.json", "versions.yml"],
        "KATANA_TXIMPORT": ["gene_txi.rds", "gene.counts.tsv", "annotation.tsv", "versions.yml"],
        "DEXSEQ_EXON": ["DEXSeqResults.B_vs_A.csv", "DEXSeqResults.B_vs_A.rds", "DEXSeqDataSet.B_vs_A.rds", "plotDEXSeq.B_vs_A.pdf", "versions.yml"],
        "DEXSEQ_DTU": ["DEXSeqResults.B-A.tsv", "DEXSeqResults.B-A.rds", "DEXSeqDataSet.B-A.rds", "versions.yml"],
        "STAGER": ["getAdjustedPValues.B-A.tsv", "getAdjustedPValues.B-A.rds", "stageRTx.B-A.rds", "versions.yml"],
        "RMATS_PREP": ["pair/rmats_temp/task.rmats", "pair/rmats_prep.log", "versions.yml"],
        "RMATS_POST": ["pair/rmats_post/SE.MATS.JCEC.txt", "pair/rmats_post/tmp/temporary.bin", "versions.yml"],
        "CAPTURE_BAM_AUDIT": ["katana_source.bam", "audit.header.sam", "audit.primary_metrics.tsv", "versions.yml"],
        "GENERIC_STATS": ["statistic.tsv", "unregistered-model.rds", "unregistered-archive.zip", "events.ioe", "native.dpsi", "native.psivec", "versions.yml"],
        "KATANA_EXPORT": ["katana_bundle/manifest.json", "katana_bundle/bam/S1.bam", "katana_bundle/bam/S1.bam.bai",
                          "katana_bundle/refs/genome.fasta", "katana_bundle/refs/annotation.gtf", "katana_bundle/quant/S1/quant.sf"],
    }
    labels = {}
    if full_config:
        # Use the real publisher configuration, with tiny byte-producing
        # stand-ins. These are not real Katana receipts or report acceptance.
        outputs.update({
            "KATANA_FLOW_COLLECT": ["collection/fixture-collection.txt"],
            "KATANA_FLOW_REPORT": ["report/fixture-report.txt"],
            "KATANA_FLOW_TASK": ["task-results/fixture/task.txt"],
        })
        labels = {"KATANA_FLOW_COLLECT": "katana_control", "KATANA_FLOW_REPORT": "katana_report",
                  "KATANA_FLOW_TASK": "katana_downstream"}
    processes = []
    for name, files in outputs.items():
        # Returning directory outputs, rather than its children separately,
        # mirrors the real index/Salmon/bundle publication cases.
        declarations = sorted({item.split("/")[0] for item in files})
        if name == "RMATS_PREP":
            declarations = ["pair/rmats_temp/*", "pair/rmats_prep.log", "versions.yml"]
        elif name == "RMATS_POST":
            declarations = ["pair/rmats_post/*", "versions.yml"]
        output_block = "\n".join(f"    path '{item}'" for item in declarations)
        commands = []
        for item in files:
            parent = str(Path(item).parent).replace("\\", "/")
            if parent != ".":
                commands.append(f"mkdir -p '{parent}'")
            commands.append(f"printf 'generated publication fixture\\n' > '{item}'")
        commands_block = "\n    ".join(commands)
        label = f"    label '{labels[name]}'\n" if name in labels else ""
        processes.append(f'''process {name} {{
{label}    input:
    val meta
    output:
{output_block}
    script:
    """
    {commands_block}
    """
}}
''')
    workflow = "\n".join(f"    {name}([id: 'S1'])" for name in outputs)
    (root / "main.nf").write_text("nextflow.enable.dsl=2\n" + "\n".join(processes) + f"\nworkflow {{\n{workflow}\n}}\n", encoding="utf-8")
    included_config = PIPELINE / "nextflow.config" if full_config else CONFIG
    escaped_config = included_config.as_posix().replace("'", "\\'")
    # The full pipeline declares production resource requests. Override only
    # this generated fixture's requests; it invokes no native biology tools.
    small_resources = '''
    cpus = 1
    memory = '64 MB'
    time = '2m'
    withName: 'STAR_GENOMEGENERATE' { cpus = 1; memory = '64 MB' }
    withLabel: katana_control { cpus = 1; memory = '64 MB'; time = '2m'; container = null }
    withLabel: katana_downstream { cpus = 1; memory = '64 MB'; time = '2m'; container = null }
    withLabel: katana_report { cpus = 1; memory = '64 MB'; time = '2m'; container = null }
''' if full_config else ""
    (root / "nextflow.config").write_text(f'''params {{
    storage_mode = '{mode}'
    outdir = 'results'
    publish_dir_mode = '{"symlink" if mode == "lean" else "copy"}'
    star_sjdb_overhang = 99
    star_genome_sa_index_nbases = null
}}
includeConfig '{escaped_config}'
process {{
    executor = 'local'
    shell = ['/bin/bash', '-euo', 'pipefail']
{small_resources}
}}
''', encoding="utf-8")


class NativeStoragePublicationTests(unittest.TestCase):
    @unittest.skipIf(os.name == "nt", "Native local Nextflow fixture needs a POSIX shell; run in Linux or WSL")
    def test_native_downstream_publishing_respects_lean_after_extra_config(self):
        command = _native_command()
        if command is None:
            self.skipTest("Set KATANA_NEXTFLOW_COMMAND_JSON to run the pinned native publication fixture")
        with tempfile.TemporaryDirectory(prefix="katana-downstream-publication-") as temporary:
            for mode in ("retain", "lean"):
                with self.subTest(mode=mode):
                    root = Path(temporary) / mode
                    root.mkdir()
                    (root / "main.nf").write_text('''nextflow.enable.dsl=2
process KATANA_FLOW_TASK {
    label 'katana_downstream'
    input:
    val spec
    output:
    path 'task-results/fixture'
    script:
    """
    mkdir -p task-results/fixture
    printf 'generated downstream publisher fixture\\n' > task-results/fixture/task.txt
    """
}
process KATANA_FLOW_COLLECT {
    label 'katana_control'
    output:
    path 'collection'
    script:
    """
    mkdir -p collection
    printf 'generated downstream publisher fixture\\n' > collection/fixture-collection.txt
    """
}
process KATANA_FLOW_REPORT {
    label 'katana_report'
    output:
    path 'report'
    script:
    """
    mkdir -p report
    printf 'generated downstream publisher fixture\\n' > report/fixture-report.txt
    """
}
workflow {
    KATANA_FLOW_TASK([id:'fixture', execution_group:'audit', resources:[cpus:1, memory:'64 MB', time:'2m']])
    KATANA_FLOW_COLLECT()
    KATANA_FLOW_REPORT()
}
''', encoding="utf-8")
                    output = root / "override-output"
                    overlay = root / "override.config"
                    overlay.write_text("params.storage_mode = '" + mode + "'\nparams.outdir = '" + output.as_posix() +
                        "'\nprocess {\n withLabel: katana_control { memory='64 MB'; time='2m' }\n" +
                        " withLabel: katana_report { cpus=1; memory='64 MB'; time='2m' }\n}\n", encoding="utf-8")
                    result = subprocess.run([*command, "-c", str(PIPELINE / "nextflow.config"), "-c", str(overlay),
                                             "run", "main.nf", "-ansi-log", "false", "-work-dir", "work"],
                                            cwd=root, capture_output=True, text=True, timeout=240)
                    self.assertEqual(result.returncode, 0, result.stdout[-6000:] + result.stderr[-6000:])
                    self.assertEqual((output / "report/fixture-report.txt").read_text(),
                                     "generated downstream publisher fixture\n")
                    self.assertFalse(any(path.is_symlink() for path in output.rglob("*")))
                    if mode == "lean":
                        self.assertEqual((output / "collection/fixture-collection.txt").read_text(),
                                         "generated downstream publisher fixture\n")
                        self.assertFalse((output / "downstream").exists())
                    else:
                        published_tasks = list((output / "downstream").rglob("task.txt"))
                        self.assertEqual(len(published_tasks), 1)
                        self.assertEqual(published_tasks[0].read_text(), "generated downstream publisher fixture\n")
                        self.assertFalse((output / "collection").exists())
                    self.assertTrue(any((root / "work").rglob("task.txt")))
                    for name in ("report", "collection", "downstream"):
                        self.assertFalse((root / "results" / name).exists(), name)

    @unittest.skipIf(os.name == "nt", "Native local Nextflow fixture needs a POSIX shell; run in Linux or WSL")
    def test_native_extra_config_overrides_policy_and_outdir_for_all_publishers(self):
        command = _native_command()
        if command is None:
            self.skipTest("Set KATANA_NEXTFLOW_COMMAND_JSON to run the pinned native publication fixture")
        with tempfile.TemporaryDirectory(prefix="katana-storage-overrides-") as temporary:
            root = Path(temporary) / "extra-config"
            _fixture(root, "retain", full_config=True)
            output = root / "overridden-results"
            overlay = root / "override.config"
            overlay.write_text("params.storage_mode = 'lean'\nparams.outdir = '" + output.as_posix() +
                               "'\nparams.publish_dir_mode = 'symlink'\n", encoding="utf-8")
            result = subprocess.run([*command, "-c", str(overlay), "run", "main.nf", "-ansi-log", "false",
                                     "-work-dir", "work"], cwd=root, capture_output=True, text=True, timeout=240)
            self.assertEqual(result.returncode, 0, result.stdout[-6000:] + result.stderr[-6000:])
            for member in ("katana_bundle/manifest.json", "katana_bundle/bam/S1.bam", "katana_bundle/bam/S1.bam.bai",
                           "upstream/fastqc/S1_fastqc.zip", "upstream/star_align/S1.Log.final.out",
                           "native_models/DEG/gene_txi.rds", "native_models/salmon/S1/aux_info/meta_info.json",
                           "collection/fixture-collection.txt", "report/fixture-report.txt"):
                self.assertEqual((output / member).read_text(), "generated publication fixture\n")
            self.assertFalse(any(path.is_symlink() for path in output.rglob("*")))
            self.assertFalse(any(output.rglob("*.fq.gz")))
            self.assertFalse(any(output.rglob("*.fastq.gz")))
            self.assertEqual([path.relative_to(output).as_posix() for path in output.rglob("*.bam")],
                             ["katana_bundle/bam/S1.bam"])
            for omitted in ("refs", "bam", "quant", "DEG", "reference_index", "downstream"):
                self.assertFalse((output / omitted).exists(), omitted)
            # A wrong early-bound publisher would write these native outcomes
            # under the original default rather than the extra-config outdir.
            for omitted in ("katana_bundle", "collection", "report", "downstream", "bam"):
                self.assertFalse((root / "results" / omitted).exists(), omitted)
            self.assertTrue(any((root / "work").rglob("S1.name_grouped.bam")))
            self.assertTrue(any((root / "work").rglob("task.txt")))

    @unittest.skipIf(os.name == "nt", "Native local Nextflow fixture needs a POSIX shell; run in Linux or WSL")
    def test_native_retain_and_lean_publish_expected_files_without_changing_work(self):
        command = _native_command()
        if command is None:
            self.skipTest("Set KATANA_NEXTFLOW_COMMAND_JSON to run the pinned native publication fixture")
        with tempfile.TemporaryDirectory(prefix="katana-storage-publication-") as temporary:
            parent = Path(temporary)
            for mode in ("retain", "lean"):
                with self.subTest(mode=mode):
                    root = parent / mode
                    _fixture(root, mode)
                    result = subprocess.run([*command, "run", "main.nf", "-ansi-log", "false", "-work-dir", "work"],
                                            cwd=root, capture_output=True, text=True, timeout=240)
                    self.assertEqual(result.returncode, 0, result.stdout[-6000:] + result.stderr[-6000:])
                    output = root / "results"
                    for member in ("manifest.json", "bam/S1.bam", "bam/S1.bam.bai", "refs/genome.fasta", "refs/annotation.gtf", "quant/S1/quant.sf"):
                        self.assertEqual((output / "katana_bundle" / member).read_text(), "generated publication fixture\n")
                    self.assertTrue((output / "upstream/fastqc/S1_fastqc.zip").is_file())
                    self.assertTrue((output / "upstream/star_align/S1.Log.final.out").is_file())
                    self.assertTrue((output / "upstream/trimgalore/S1_trimming_report.txt").is_file())
                    self.assertTrue((output / "upstream/capture_bam_audit/S1/audit.header.sam").is_file())
                    self.assertTrue((output / "upstream/generic_stats/statistic.tsv").is_file())
                    self.assertTrue((output / "upstream/generic_stats/unregistered-model.rds").is_file())
                    self.assertTrue((output / "upstream/generic_stats/unregistered-archive.zip").is_file())
                    self.assertTrue((output / "upstream/generic_stats/events.ioe").is_file())
                    self.assertTrue((output / "upstream/generic_stats/native.dpsi").is_file())
                    self.assertTrue((output / "upstream/generic_stats/native.psivec").is_file())
                    self.assertTrue(any((output / "upstream/rmats_prep").rglob("rmats_prep.log")))
                    self.assertFalse(any(output.rglob("katana_source.bam")))
                    if mode == "lean":
                        self.assertFalse(any(path.is_symlink() for path in output.rglob("*")))
                        self.assertFalse(any(output.rglob("*.fq.gz")))
                        self.assertFalse(any(output.rglob("*.fastq.gz")))
                        self.assertEqual([path.relative_to(output).as_posix() for path in output.rglob("*.bam")],
                                         ["katana_bundle/bam/S1.bam"])
                        self.assertFalse((output / "refs").exists())
                        self.assertFalse((output / "bam").exists())
                        self.assertFalse((output / "quant").exists())
                        self.assertFalse((output / "DEG").exists())
                        self.assertFalse((output / "reference_index").exists())
                        self.assertTrue((output / "native_models/DEG/gene_txi.rds").is_file())
                        self.assertTrue((output / "native_models/salmon/S1/aux_info/meta_info.json").is_file())
                        self.assertTrue((output / "native_models/salmon/S1/lib_format_counts.json").is_file())
                        self.assertTrue((output / "native_models/dexseq_exon/DEXSeqResults.B_vs_A.rds").is_file())
                        self.assertTrue((output / "native_models/dexseq_exon/plotDEXSeq.B_vs_A.pdf").is_file())
                        self.assertTrue((output / "native_models/dtu/dexseq/DEXSeqDataSet.B-A.rds").is_file())
                        self.assertTrue((output / "native_models/dtu/stager/stageRTx.B-A.rds").is_file())
                        self.assertFalse(any(output.rglob("task.rmats")))
                        self.assertFalse(any(output.rglob("temporary.bin")))
                    else:
                        self.assertTrue((output / "reference_index/star-index/Genome").is_file())
                        self.assertTrue((output / "upstream/trimgalore/S1_val_1.fq.gz").is_file())
                        self.assertTrue((output / "upstream/star_align/S1.Aligned.out.bam").is_file())
                        self.assertTrue((output / "upstream/collate_genome_bam/S1.name_grouped.bam").is_file())
                        self.assertTrue((output / "bam/S1.coordinate.bam").is_file())
                        self.assertTrue((output / "refs/genome.fasta").is_file())
                        self.assertTrue((output / "quant/S1/quant.sf").is_file())
                        self.assertTrue((output / "DEG/gene_txi.rds").is_file())
                    # Publication never removes its live producers. A separate
                    # managed phase may clean work only after handoff checks.
                    self.assertTrue(any((root / "work").rglob("S1.name_grouped.bam")))
                    self.assertTrue(any((root / "work").rglob("S1_val_1.fq.gz")))


if __name__ == "__main__":
    unittest.main()
